    "Items": [
      {
        "Type": "POLICY_LIBERTY",
        "Name": "Progress",
        "Help": "Progress plans to found a sprawl of self-sufficient Cities in the early game with free starting yields and faster rate of tile improvement. Constructing Buildings and birthing Citizens supports the economy throughout the game.\nAdopting Progress grants:\n* Receive an instant boost of 75 Science.\n* Receive 10 Science when a Citizen is born, scaling with Era.\n* Receive 15 Culture when a Technology is researched, scaling with Era, and for every Technology already unlocked (not scaling with Era).\nEach Progress policy unlocked grants:\n* Gain an additional 15 Culture when a Technology is researched, scaling with Era.\nAdopting all policies in Progress grants:\n* Unlocks building the Forbidden Palace.\n* Receive 25 Gold when a Citizen is born in any city, scaling with Era.\n* Allows for the purchase of Great Writers with Faith starting in the Industrial Era.",
        "Era": "Ancient",
        "Branch": "Progress",
        "Level": 0,
        "PrereqPolicies": []
      }
    ]
  }
}

{
  "subject": "policies",
